# Listening scripts for Lessons 5-13 + exams, exported from v5build data (same text as Level2_Curriculum_v5.md).
LESSONS = {'L5': ('Lesson five. Listening. It is Monday morning. Kim and Marco talk at work. Listen.', [('Kim', 'Good morning, Marco! How was your weekend?'), ('Marco', 'It was great, thanks. On Saturday, I visited my sister. We cooked a big lunch together.'), ('Kim', 'That sounds nice. Was the food good?'), ('Marco', 'Yes, it was. It was delicious! And on Sunday, I played soccer in the park. How about you? How was your weekend?'), ('Kim', 'It was boring. I was very busy. On Saturday, I worked all day.'), ('Marco', 'Oh no. And on Sunday?'), ('Kim', 'On Sunday, I cleaned the house, and I washed the clothes. In the evening, I watched a movie.'), ('Marco', 'Was it good?'), ('Kim', "No, it wasn't. It was terrible! I stopped it after twenty minutes."), ('Marco', 'Ha! Were you tired this morning?'), ('Kim', "Yes, I was. I was very tired. But I'm happy it's Monday. Work is easier!")]), 'L6': ('Lesson six. Listening. Sam talks to Ana for the class newsletter. Listen.', [('Sam', 'Ana, thank you for talking to me. Where did you grow up?'), ('Ana', 'I grew up in a small town by the sea. I went to school there.'), ('Sam', 'When did you move to this city?'), ('Ana', 'I moved here eight years ago. I came with my sister.'), ('Sam', 'Did you speak English then?'), ('Ana', "No, I didn't. I only knew three words: hello, thank you, and pizza!"), ('Sam', 'Ha! Did you find a job quickly?'), ('Ana', 'Yes, I did. I got my first job after two weeks. I made sandwiches in a coffee shop.'), ('Sam', 'How did you feel?'), ('Ana', 'I felt nervous every day. But I met a lot of nice people.'), ('Sam', 'And you met your husband there, right?'), ('Ana', "That's right! We got married five years ago. Now we have a little boy."), ('Sam', 'What a story! Thank you, Ana.')]), 'L7': ('Lesson seven. Listening. Rosa and Carlos talk about getting to work. Listen.', [('Carlos', 'Rosa, how do you get to work?'), ('Rosa', 'I usually take the bus. How about you?'), ('Carlos', 'I drive. The car is faster than the bus.'), ('Rosa', "That's true. How long does it take?"), ('Carlos', 'It takes twenty minutes by car. And by bus?'), ('Rosa', "It takes forty-five minutes. The bus is slower, but it's cheaper. Gas is very expensive!"), ('Carlos', "You're right. And parking is expensive too. Ten dollars a day!"), ('Rosa', "Wow. Also, on the bus, I can read. It's more relaxing than driving."), ('Carlos', 'Is the bus crowded?'), ('Rosa', "In the morning, yes. It's more crowded in the morning than at night."), ('Carlos', "Maybe I can try my bike. A bike is cheaper than a car, and it's better for my health."), ('Rosa', "Yes, but it's worse in the rain!")]), 'L8': ('Lesson eight. Listening. Kim is new in the neighborhood. She asks Rosa for help. Listen.', [('Kim', "Rosa, I need some help. Where's the best supermarket around here?"), ('Rosa', "Fresh Market is the biggest, and the fruit is the freshest. But it's expensive."), ('Kim', 'Hmm. Is there a cheaper supermarket?'), ('Rosa', "Yes. Value Foods is the cheapest. It's on Lake Street."), ('Kim', 'Great. Are there any pharmacies near here?'), ('Rosa', 'Yes, there are two. The closest one is on Pine Street, next to the bank.'), ('Kim', "Perfect. And what's the best restaurant in town?"), ('Rosa', "I think The Sunny Kitchen is the best. The food is delicious, and it's not expensive."), ('Kim', 'And is there a park for my kids?'), ('Rosa', "Yes! Lake Park is the most beautiful park in town. It's the best place on a sunny day."), ('Kim', "Thank you, Rosa. You're the best neighbor!")]), 'L9': ('Lesson nine. Listening. Sam and Ana are at a restaurant. Listen.', [('Server', 'Hi! Are you ready to order?'), ('Ana', "Yes, please. I'd like the chicken soup."), ('Server', 'Sure. The soup comes with some bread. And for you?'), ('Sam', 'Do you have any fish today?'), ('Server', "Sorry, we don't have any fish today."), ('Sam', 'Okay. Can I have a chicken sandwich and a salad, please?'), ('Server', 'Of course. Anything to drink?'), ('Ana', 'Can I have some water, please? No ice.'), ('Sam', "I'd like a coffee with milk, please."), ('Server', 'How much sugar?'), ('Sam', 'Two sugars, please.'), ('N', 'Later.'), ('Ana', 'Excuse me. Can we have the check, please?'), ('Server', "Here you go. That's twenty-four fifty."), ('Sam', 'Thank you. Everything was delicious!')]), 'L10': ('Lesson ten. Listening. Marco is sick. He calls Riverside Clinic. Listen.', [('Receptionist', 'Good morning, Riverside Clinic. How can I help you?'), ('Marco', "Hi. I'd like to make an appointment, please. I'm sick."), ('Receptionist', "I'm sorry. What's the matter?"), ('Marco', 'I have a bad cough and a sore throat. And I have a fever.'), ('Receptionist', 'When did it start?'), ('Marco', 'Three days ago.'), ('Receptionist', 'Okay. The doctor can see you today at ten fifteen.'), ('Marco', "Sorry, I can't come at ten fifteen. Is there a later time?"), ('Receptionist', 'Yes. How about three thirty?'), ('Marco', 'Three thirty is fine. Thank you.'), ('Receptionist', "What's your name, please?"), ('Marco', 'Marco Silva.'), ('Receptionist', "Okay, Mr. Silva. For now, you should rest and drink a lot of water. And you shouldn't go to work today."), ('Marco', 'Okay. Thank you very much.')]), 'L11': ('Lesson eleven. Listening. Kim calls Carlos. Listen.', [('Carlos', 'Hello?'), ('Kim', "Hi, Carlos! It's Kim. Are you free this weekend?"), ('Carlos', "Hi, Kim! I'm not sure. Why?"), ('Kim', "We're going to have a picnic at Lake Park on Saturday. Would you like to come?"), ('Carlos', "I'd love to! What time?"), ('Kim', "At two o'clock."), ('Carlos', "Great. I'm working in the morning, but I'm free in the afternoon. Is Rosa going to come?"), ('Kim', "No, she isn't. She's going to visit her mother."), ('Carlos', "Okay. I'm going to bring a ball. We can play soccer!"), ('Kim', 'Good idea. And do you want to go to the movies on Sunday?'), ('Carlos', "Sorry, I can't. I'm helping my brother on Sunday. He's moving to a new apartment."), ('Kim', 'No problem. See you on Saturday!'), ('Carlos', 'See you then. Thanks for inviting me!')]), 'L12': ('Lesson twelve. Listening. Sam calls City Phone. His phone bill is too high. Listen.', [('Agent', 'Thank you for calling City Phone customer service. How can I help you?'), ('Sam', "Hi. I have a question about my bill. It's too high."), ('Agent', 'I can help with that. Could you give me your account number, please?'), ('Sam', "Yes. It's four, seven, two, nine, one, six."), ('Agent', 'Sorry, could you repeat that, please?'), ('Sam', 'Sure. Four, seven, two, nine, one, six.'), ('Agent', "Thank you. And what's your last name?"), ('Sam', 'Lopez.'), ('Agent', 'Can you spell that, please?'), ('Sam', 'L. O. P. E. Z.'), ('Agent', "Thank you, Mr. Lopez. Let me check. Yes, I see the problem. We charged you two times this month. I'm sorry."), ('Sam', 'Okay. Do I have to pay the full bill?'), ('Agent', "No, you don't have to. You only need to pay forty-five dollars."), ('Sam', 'When do I have to pay?'), ('Agent', 'You have to pay by the fifteenth.'), ('Sam', 'Great. Could you send me a new bill, please?'), ('Agent', 'Of course. Is there anything else?'), ('Sam', "No, that's all. Thank you very much.")]), 'L13': ('Lesson thirteen. Listening. Ana gives a short talk at graduation. Listen.', [('Ana', 'Good evening, everyone. My name is Ana.'), ('Ana', "One year ago, I was very nervous. I didn't understand people at the store. I was afraid to talk on the phone."), ('Ana', 'Then I started this class. I came to class every week. I practiced a lot with my classmates.'), ('Ana', 'Now, I work at a bakery. I talk to customers every day. I make my own appointments at the clinic. I feel proud.'), ('Ana', 'Next year, I am going to take a computer class. My goal is to get an office job. My dream is to help other people learn English.'), ('Ana', 'Thank you to my teachers and to my classmates. You helped me a lot. Thank you!')]), 'Midterm': ('Midterm listening. Sam meets Kim on the street. Listen.', [('Sam', 'Kim! Hi! How are you?'), ('Kim', "Hi, Sam! I'm great, thanks. I moved last week. I live on Maple Street now."), ('Sam', 'Really? Do you like it?'), ('Kim', "Yes, I love it. There's a big park near my apartment. On Sunday, I walked in the park. It was beautiful."), ('Sam', 'Nice! Do you still work at the bank?'), ('Kim', 'Yes, I do. I work at a bank downtown. I start at eight thirty.'), ('Sam', 'How do you get to work?'), ('Kim', "I take the train now. It's faster than the bus. It takes twenty-five minutes."), ('Sam', "That's good. What are you doing right now?"), ('Kim', "I'm waiting for a delivery. My new sofa is coming today!"), ('Sam', 'Oh, nice. Do you cook in your new kitchen?'), ('Kim', 'Of course! I love cooking. Come for dinner sometime!'), ('Sam', 'Thanks, Kim! See you soon.')]), 'Final': ('Final listening. Rosa meets Marco at the supermarket. Listen.', [('Marco', 'Hi, Rosa! How are you?'), ('Rosa', "Not great. I have a headache, and I'm very tired."), ('Marco', 'Oh no. You should drink water and rest. Do you need any medicine?'), ('Rosa', 'Yes. Is there a pharmacy near here?'), ('Marco', "Yes. The closest pharmacy is next to the bank. It's also the cheapest."), ('Rosa', 'Thanks. What are you buying?'), ('Marco', "Some rice, six eggs, and a chicken. I'm going to cook for a party."), ('Rosa', 'A party? When?'), ('Marco', "On Saturday at four o'clock. It's my son's birthday. Would you like to come?"), ('Rosa', "I'd love to! Can I bring something?"), ('Marco', 'Sure. Could you bring a salad?'), ('Rosa', 'Of course. How many people are going to come?'), ('Marco', "About twenty. It's going to be the biggest party of the year!")])}
